*/
std::vector<HashedPassword> hash_passwords(int count, const std::vector<std::string>& usernames, const std::vector<std::string>& passwords) {
    std::vector<HashedPassword> hashed_passwords(count);
    // BEGIN SOLUTION
    for (int i = 0; i < count; i++) {
